import java.util.*;import java.util.regex.*;
abstract class Question {String correct,answer;double points;Question(String c,String a,double p){correct=c;answer=a;points=p;}abstract double grade();abstract String getType();}
class MCQ extends Question {MCQ(String c,String a,double p){super(c,a,p);}double grade(){return correct.equalsIgnoreCase(answer)?points:0;}String getType(){return "MCQ";}}
class TF extends Question {TF(String c,String a,double p){super(c,a,p);}double grade(){return correct.equalsIgnoreCase(answer)?points:0;}String getType(){return "TF";}}
class Essay extends Question {Essay(String c,String a,double p){super(c,a,p);}double grade(){String[] keywords=correct.split(",");int count=0;String text=answer.toLowerCase();for(String word:keywords){String k=word.trim().toLowerCase();if(Pattern.compile("\\b"+Pattern.quote(k)+"\\b").matcher(text).find())count++;}if(count>=2)return points*.75;else if(count==1)return points*.50;return 0;}String getType(){return "ESSAY";}}
public class ExaminationQuestionGrader {public static void main(String[] args){Scanner sc=new Scanner(System.in);int n=Integer.parseInt(sc.nextLine());double total=0;Pattern p=Pattern.compile("\"([^\"]*)\"");for(int i=0;i<n;i++){String line=sc.nextLine();String type=line.substring(0,line.indexOf(' '));Matcher m=p.matcher(line);List<String> v=new ArrayList<>();while(m.find())v.add(m.group(1));String correct=v.get(1),answer=v.get(2);double points=Double.parseDouble(line.substring(line.lastIndexOf('"')+1).trim());Question q;switch(type){case "MCQ":q=new MCQ(correct,answer,points);break;case "TF":q=new TF(correct,answer,points);break;default:q=new Essay(correct,answer,points);}double score=q.grade();System.out.printf("%s: %.2f%n",q.getType(),score);total+=score;}System.out.printf("Total Score: %.2f%n",total);sc.close();}}